//! Raw FFI bindings for QNX 8.0 native message passing, pulses, named channels,
//! timers and the resource-manager framework.
//!
//! Almost everything here is generated by bindgen at build time from the QNX SDP 8.0
//! headers listed in `wrapper.h` (the build needs `QNX_TARGET`). Function-like macros
//! that bindgen cannot translate are written by hand at the end of this file.
//!
//! The items mirror the C API one to one and keep its names. Calling the QNX
//! functions is `unsafe`. Use the `qnx-ipc` crate for a safe interface.
#![allow(non_snake_case)]

/// The bindgen output, with lints for C naming and generated code turned off.
#[allow(
    non_upper_case_globals,
    non_camel_case_types,
    dead_code,
    missing_docs,
    clippy::all
)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

pub use generated::*;

use core::ffi::{c_int, c_short, c_void};

/// Fills `ev` so that the event is delivered as a pulse on connection `coid`
/// with priority `priority`, code `code` and pointer value `value`.
///
/// Hand-written form of the C macro `SIGEV_PULSE_INIT` from `<sys/siginfo.h>`,
/// which bindgen cannot translate. See
/// <https://www.qnx.com/developers/docs/8.0/com.qnx.doc.neutrino.lib_ref/topic/s/sigevent.html>.
#[inline]
pub fn SIGEV_PULSE_INIT(
    ev: &mut sigevent,
    coid: c_int,
    priority: c_short,
    code: c_short,
    value: *mut c_void,
) {
    ev.sigev_notify = SIGEV_PULSE as c_int;
    ev.__sigev_un1.__sigev_coid = coid;
    ev.__sigev_un2.__st.__sigev_priority = priority;
    ev.sigev_value.sival_ptr = value;
    ev.__sigev_un2.__st.__sigev_code = code;
}

/// Resource-manager handler return value that asks the framework to do its default
/// action (usually reply `ENOSYS`).
///
/// Hand-written form of `_RESMGR_DEFAULT` (`INT_MIN + 1`) from `<sys/resmgr.h>`. See
/// <https://www.qnx.com/developers/docs/8.0/com.qnx.doc.neutrino.lib_ref/topic/r/resmgr_io_funcs_t.html>.
pub const _RESMGR_DEFAULT: c_int = c_int::MIN + 1;

/// Resource-manager handler return value that replies with the first `num` parts of
/// `ctp->iov`.
///
/// Hand-written form of the C macro `_RESMGR_NPARTS(num)` from `<sys/resmgr.h>`. See
/// <https://www.qnx.com/developers/docs/8.0/com.qnx.doc.neutrino.lib_ref/topic/r/resmgr_io_funcs_t.html>.
#[inline]
pub const fn _RESMGR_NPARTS(num: c_int) -> c_int {
    -num
}

/// Resource-manager handler return value that replies with status `err` (an errno
/// value, or `EOK`) and no data.
///
/// Hand-written form of the C macro `_RESMGR_ERRNO(err)` from `<sys/resmgr.h>`. See
/// <https://www.qnx.com/developers/docs/8.0/com.qnx.doc.neutrino.lib_ref/topic/r/resmgr_io_funcs_t.html>.
#[inline]
pub const fn _RESMGR_ERRNO(err: c_int) -> c_int {
    err
}
